const makeSections = (rows: string[], concept?: string): GlossaryLearningSection[] => {
  const titles = [
    "Definition",
    "Purpose and Importance",
    "How It Works",
    "Core Components",
    "Architecture",
    "Real-Time Project Example",
    "Practical Workflow",
    "Commands and Configuration",
    "Security Considerations",
    "High Availability and Reliability",
    "Monitoring and Troubleshooting",
    "Common Mistakes",
    "Best Practices",
  ];

  if (rows.length !== titles.length) {
    throw new Error(`Expected ${titles.length} AWS learning sections, received ${rows.length}`);
  }

  const teluguRows = concept ? awsTeluguExplanations[concept] : undefined;

  if (teluguRows && teluguRows.length !== rows.length) {
    throw new Error(`${concept}: English/Telugu section count mismatch`);
  }

  return rows.map((explanation, index) => ({
    title: titles[index],
    items: [{
      title: titles[index],
      explanation,
      ...(teluguRows ? { teluguExplanation: teluguRows[index] } : {}),
    }],
  }));
};

